const sqlite3 = require('sqlite3');
const db = new sqlite3.Database('/workspace/world.db');
db.all(\"SELECT name FROM sqlite_master WHERE type='table'\", (err, rows) => {
  console.log('Tables:', rows.map(r => r.name));
});
" 2>/dev/null

